import { registerWebComponents } from '@domg-wc/common';
import { VlHeaderNext } from '@domg-wc/components/compliance';

registerWebComponents([VlHeaderNext]);

// In 2.7.0 volgt ready op window, niet op het element (vanaf 2.19.0 op het element zelf), zodra de widget gemount
// is. Vanaf dan geeft height de hoogte van de header.
window.addEventListener('ready', () => {
    console.log(document.querySelector('vl-header-next').height);
});

import { registerWebComponents } from '@domg-wc/common';
import { VlHeaderNext } from '@domg-wc/components/compliance';

registerWebComponents([VlHeaderNext]);

// vl-header-next geeft applicationLinks één keer door aan de widget, na het mounten: zet de property meteen.
document.querySelector('vl-header-next').applicationLinks = [
    { label: 'Link 1', href: 'https://example.com/link1' },
    { label: 'Link 2', href: 'https://example.com/link2' },
];
